/**
 * jixoai page scaffold styles (registry/files/ui/app-shell.css).
 * Import once per site alongside app-shell.svelte.
 *
 * Systematized MPA view transitions (2026-08-20):
 * 1. `@view-transition { navigation: auto; }` enables cross-document
 *    transitions (Chrome/Edge 126+; other browsers navigate normally).
 * 2. Named elements: the sticky header band is "site-header" — it persists
 *    between pages (the nav never flickers); the main column is
 *    "page-main" — it is the thing that animates.
 * 3. The page navigation is a horizontal slide paired with a blur
 *    crossfade: the old page exits toward the left while blurring out,
 *    the new page enters from the right while sharpening in. Duration and
 *    easing follow the jixoai motion law (sub-300ms UI, ease-out).
 * 4. Route-typed variants: consumers that wire
 *    view-transitions-toolkit's useAutoTypes() (render-blocking, in
 *    <head>) get from-/to-<route> types; a `jx-vt-direction` attribute on
 *    <html> (set by the toolkit or manually) can flip the slide axis.
 */

@view-transition {
  navigation: auto;
}

.jx-skip-link {
  clip-path: inset(50%);
  height: 1px;
  left: 0;
  overflow: hidden;
  position: absolute;
  top: 0;
  white-space: nowrap;
  width: 1px;
  z-index: 100;
}
.jx-skip-link:focus-visible {
  clip-path: none;
  height: auto;
  width: auto;
  padding: 0.5rem 0.75rem;
  background: var(--background);
  color: var(--foreground);
  outline: 1px solid var(--border);
  outline-offset: -1px;
}

.jx-page-main {
  view-transition-name: page-main;
}

/* The scaffold's sticky band holds the persistent header. The header
   itself must carry view-transition-name: site-header — set on the band
   wrapper so consumer headers need no changes. */
.jx-scaffold-header {
  view-transition-name: site-header;
}

/* ── the page navigation animation: horizontal slide + blur ── */
::view-transition-old(page-main) {
  animation: 240ms cubic-bezier(0.22, 0.61, 0.36, 1) both jx-slide-out;
}
::view-transition-new(page-main) {
  animation: 280ms cubic-bezier(0.22, 0.61, 0.36, 1) both jx-slide-in;
}

@keyframes jx-slide-out {
  to {
    transform: translateX(-6%);
    filter: blur(6px);
    opacity: 0.4;
  }
}
@keyframes jx-slide-in {
  from {
    transform: translateX(6%);
    filter: blur(6px);
    opacity: 0.4;
  }
}

/* Reduced motion: crossfade only, no travel, no blur. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(page-main),
  ::view-transition-new(page-main) {
    animation: 120ms ease-out both;
  }
  ::view-transition-old(page-main) {
    to {
      opacity: 0;
    }
  }
  ::view-transition-new(page-main) {
    from {
      opacity: 0;
    }
  }
}
